gW4(){return"\ub3c5\uc5d0 \uac78\ub9b0 Ovaling\uc740 \uc790\uc2e0\uc758 \ud134\uc774 \uc2dc\uc791\ub420 \ub54c\ub9c8\ub2e4 \ucd5c\ub300 <hp>\uccb4\ub825</hp>\uc758 \uc77c\ubd80\ub97c \uc783\uc5b4\uc694. \ub3c5\uc740 <def>\ubc29\uc5b4\ub825</def>\uc744 \ubb34\uc2dc\ud574\uc694. \ub2e4\ub978 \ud53c\ud574\ucc98\ub7fc \ubcf4\ud638\ub9c9\uc774 \uba3c\uc800 \ud761\uc218\ud574\uc694. \uc815\ud574\uc9c4 \ud134\uc774 \uc9c0\ub098\uba74 \ub05d\ub098\uc694."},
gWh(){return"\ub2e4\uc74c \ud134\uc744 \uac74\ub108\ub6f0\uc5b4\uc694."},
gWi(){return"\uae30\uc808\ud55c Ovaling\uc740 \ud134\uc744 \uac74\ub108\ub6f0\uace0 \uc544\ubb34\uac83\ub3c4 \ud560 \uc218 \uc5c6\uc5b4\uc694. \ubcf4\uc2a4\ub294 \uae30\uc808\uc5d0 \uba74\uc5ed\uc778 \uacbd\uc6b0\uac00 \ub9ce\uace0, \uc77c\ubd80 Ovaling\uc740 \ud328\uc2dc\ube0c\ub85c \ub9c9\uc744 \uc218 \uc788\uc5b4\uc694."},
gWd(){return"<spd>\uc18d\ub3c4</spd>\uac00 \ub0ae\uc544\uc838 \ub35c \uc790\uc8fc \ud589\ub3d9\ud574\uc694."},
gWe(){return"\uc18d\ub3c4 \uac10\uc18c\ub294 \uc9c0\uc18d\ub418\ub294 \ub3d9\uc548 <spd>\uc18d\ub3c4</spd>\ub97c \uc77c\uc815 \ube44\uc728 \ub0ae\ucdb0\uc694. \ud134 \uac8c\uc774\uc9c0\uac00 \ub290\ub9ac\uac8c \ucc28\uc11c Ovaling\uc758 \ud134\uc774 \ub2a6\uac8c, \ub35c \uc790\uc8fc \uc640\uc694."},
gVI(){return"<spd>\uc18d\ub3c4</spd>\uac00 \ub192\uc544\uc838 \ub354 \uc790\uc8fc \ud589\ub3d9\ud574\uc694."},
