gVU(){return"\uc785\ud78c \ud53c\ud574\uc758 \uc77c\ubd80\ub9cc\ud07c \ud68c\ubcf5\ud574\uc694."},
gVV(){return"\uacf5\uaca9\uc790\uac00 \uc785\ud78c \ud53c\ud574\uc758 \uc77c\ubd80\uac00 \ud0c0\uaca9\ub9c8\ub2e4 <hp>\uccb4\ub825</hp>\uc73c\ub85c \ub3cc\uc544\uc640\uc694."},
gVW(){return"\ud134 \uac8c\uc774\uc9c0 \uc77c\ubd80\ub97c \ube44\uc6cc\uc694."},
gVX(){return"\ud134 \uac8c\uc774\uc9c0 \uac10\uc18c\ub294 \ub300\uc0c1\uc758 \ud134 \uac8c\uc774\uc9c0\ub97c \uc77c\uc815 \ube44\uc728 \uae4e\uc544 \ub2e4\uc74c \ud134\uc774 \ub2a6\uac8c \uc640\uc694."},
gVY(){return"\ud134 \uac8c\uc774\uc9c0 \uc77c\ubd80\ub97c \ucc44\uc6cc\uc694."},
gVZ(){return"\ud134 \uac8c\uc774\uc9c0 \uc99d\uac00\ub294 \ub300\uc0c1\uc758 \ud134 \uac8c\uc774\uc9c0\ub97c \uc77c\uc815 \ube44\uc728 \ucc44\uc6cc \ub2e4\uc74c \ud134\uc774 \ube68\ub9ac \uc640\uc694."},
gVs(){return"\ubaa8\ub4e0 \uc57d\ud654 \ud6a8\uacfc\ub97c \uc81c\uac70\ud574\uc694."},
gVt(){return"\uc815\ud654\ub294 \ub300\uc0c1\uc758 \ubaa8\ub4e0 \uc57d\ud654 \ud6a8\uacfc\ub97c \ud55c \ubc88\uc5d0 \uc81c\uac70\ud574\uc694. \uc608\ub97c \ub4e4\uc5b4 \ub3c5, \uae30\uc808, <atk>\uacf5\uaca9\ub825</atk>, <def>\ubc29\uc5b4\ub825</def>, <spd>\uc18d\ub3c4</spd> \uac10\uc18c\uac00 \ubaa8\ub450 \uc0ac\ub77c\uc838\uc694. \uac15\ud654 \ud6a8\uacfc\uc640 \ubcf4\ud638\ub9c9\uc740 \ub0a8\uc544\uc694."},
gW7(){return"\uc4f0\ub7ec\uc9c4 \uc544\uad70\uc744 \ub418\uc0b4\ub824\uc694."},
gW8(){return"\ubd80\ud65c\uc740 \uc4f0\ub7ec\uc9c4 Ovaling\uc744 <hp>\uccb4\ub825</hp> \uc77c\ubd80\uc640 \ud568\uaed8 \uc804\ud22c\ub85c \ub418\ub3cc\ub824\uc694. \uac01 Ovaling\uc740 \uc804\ud22c\ub9c8\ub2e4 \ud55c \ubc88\ub9cc \ubd80\ud65c\ud560 \uc218 \uc788\uc5b4\uc694."},
gTV(){return"<fx:poison>\ub3c5</fx>\uc5d0 \uba74\uc5ed."},
gTW(){return"\uc5ec\uc655\uc758 <fx:poison>\ub3c5</fx>\uc740 \ucd5c\ub300 3\ubc88 \uc911\ucca9\ub3fc\uc694."},
gTU(){return"\ub3c5\uc758 \ud53c: \uc5ec\uc655\uc744 \uc9c1\uc811 \uacf5\uaca9\ud558\uba74 25% \ud655\ub960\ub85c <fx:poison>\uc911\ub3c5</fx>\ub3fc\uc694 (2\ud134 \ub3d9\uc548 \ud134\ub9c8\ub2e4 \ucd5c\ub300 <hp>\uccb4\ub825</hp>\uc758 3%)."},
TL(a){return"\uac11\uc637: \uce58\uba85\ud0c0\ub9cc \ud53c\ud574\ub97c \uc8fc\uace0 \ub098\uba38\uc9c0\ub294 \ubaa8\ub450 \ud295\uaca8 \ub098\uac00\uc694. \uc774 \ubcf4\uc2a4\ub97c \uc0c1\ub300\ub85c\ub294 <crit>\uce58\uba85\ud0c0 \ud655\ub960</crit>\uc774 "+a+"%p \ub0ae\uc544\uc9c0\uba70, \ud655\uc815 \uce58\uba85\ud0c0\ub294 \ud56d\uc0c1 \uc801\uc911\ud574\uc694."},
U_(a){return"\ud314 \uc655\uad00: \ubaa8\ub4e0 \ud314\uc774 \uacf5\uaca9\ud560 \uc218 \uc788\uc5b4\uc694. \ubca0\uc5b4 \ub0b4\uba74 \uc5ec\uc655\uc774 \uc57d\ud574\uc838\uc694. \uc5ec\uc655\uc758 \ud134\uc774 \ub05d\ub0a0 \ub54c\ub9c8\ub2e4 \uac01\uac01 "+a+"% \ud655\ub960\ub85c \uacf5\uaca9\ud574\uc694."},
U0(a){return"\uc7ac\uc0dd: <hp>\uccb4\ub825</hp>\uc774 \ucc98\uc74c\uc73c\ub85c "+a+"% \uc544\ub798\ub85c \ub5a8\uc5b4\uc9c0\uba74 \ud314 \ud558\ub098\uac00 \ub2e4\uc2dc \uc790\ub77c\uc694."},
gvf(){return"\uc11d\ud654\uc758 \ub208\ube5b: \ub208\ube5b\uc774 \uac00\uc7a5 \uac15\ud55c Ovaling\uc744 <fx:petrify>\ub3cc</fx>\ub85c \ub9cc\ub4e4\uc5b4\uc694. <fx:heal>\ud68c\ubcf5</fx>\ud558\uac70\ub098 <fx:cleanse>\uc815\ud654</fx>\ud558\uba74 \ub2e4\uc2dc \ud480\ub824\ub098\uc694."},
JB(a,b,c,d){return""+a+"% \ud655\ub960\ub85c "+b+" "+c+" \ub3d9\uc548 [!\ud68c\ubcf5 \uac10\uc18c!]\ub97c \uc918\uc694: \ud68c\ubcf5\ub7c9\uc774 "+d+"% \uc904\uc5b4\uc694."},
JC(a,b,c){return a+" "+b+" \ub3d9\uc548 [!\ud68c\ubcf5 \uac10\uc18c!]\ub97c \uc918\uc694: \ud68c\ubcf5\ub7c9\uc774 "+c+"% \uc904\uc5b4\uc694."},
Jy(a){return"[!\ub3c5 \ubc29\ucd9c!]: "+a+" \uac78\ub9b0 \ubaa8\ub4e0 \ub3c5\uc774 \ub0a8\uc740 \ud53c\ud574\ub97c \ud55c\uaebc\ubc88\uc5d0 \uc785\ud788\uace0 \uc0ac\ub77c\uc838\uc694."},
gVK(){return"\ub300\uc0c1\uc774 \ubc1b\ub294 \ud68c\ubcf5\uc774 \uc904\uc5b4\uc694."},
gVL(){return"\uc9c0\uc18d\ub418\ub294 \ub3d9\uc548 \ub300\uc0c1\uc774 \ubc1b\ub294 \ubaa8\ub4e0 \ud68c\ubcf5\uc774 \uc2a4\ud0ac \uac12\ub9cc\ud07c \uc904\uc5b4\uc694. \ud761\ud608\uacfc \uc9c0\uc18d \ud68c\ubcf5\ub3c4 \ud3ec\ud568\uc774\uc5d0\uc694. \uc815\ud654\ub85c \uc5c6\uc568 \uc218 \uc788\uc5b4\uc694."},
gVE(){return"\ub3c5\uc774 \ubaa8\ub4e0 \ud53c\ud574\ub97c \ud55c\uaebc\ubc88\uc5d0 \uc785\ud600\uc694."},
gVF(){return"\ub300\uc0c1\uc5d0 \uac78\ub9b0 \ubaa8\ub4e0 \ub3c5\uc774 \uc704\ub825\uc5d0 \ub0a8\uc740 \ud134 \uc218\ub97c \uacf1\ud55c \ud53c\ud574\ub97c \uc989\uc2dc \uc785\ud788\uace0 \uc0ac\ub77c\uc838\uc694. \ub3c5\uc774 \uc5c6\uc73c\uba74 \uc544\ubb34 \uc77c\ub3c4 \uc5c6\uc5b4\uc694. \ub9c9\uc744 \uc218 \uc5c6\uc5b4\uc694."},
gUa(){return"\ub3c5\uc758 \ub2aa"},
gUb(){return"\ud300: \ube5b\uacfc \uadf8\ub9bc\uc790"},
gVA(){return"\ubc1b\ub294 \ubaa8\ub4e0 \ud53c\ud574\uac00 \uc904\uc5b4\uc694."},
gW1(){return"\ud134\uc744 \uac74\ub108\ub6f0\uace0 \ubc1b\ub294 \ud53c\ud574\uac00 \uc808\ubc18\uc774 \ub3fc\uc694."},
gVB(){return"\ubc1b\ub294 \ubaa8\ub4e0 \ud53c\ud574\uac00 \uadf8 \uac12\ub9cc\ud07c \uc904\uc5b4\uc694. \ubaa8\ub4e0 \ubcf4\ud638\ub9c9\uc740 \ubc84\ud2f0\ub294 \ub3d9\uc548 \uc790\uccb4 \ud53c\ud574 \uac10\uc18c\ub97c \uc8fc\uc9c0\ub9cc, \uc9c0\uc18d \uc2dc\uac04\uc774 \uc788\ub294 \ubcc4\ub3c4 \ud6a8\uacfc\ub85c\ub3c4 \uac78\ub9b4 \uc218 \uc788\uc5b4\uc694. \ubaa8\ub4e0 \uac10\uc18c\ub97c \ud569\uccd0 \ucd5c\ub300 50%\uc608\uc694."},
gW2(){return"\ub3cc\uc774 \ub41c Ovaling\uc740 \ud134\uc744 \uac74\ub108\ub6f0\uace0 \ubc1b\ub294 \ud53c\ud574\uac00 \uc808\ubc18\uc774 \ub3fc\uc694. \ud68c\ubcf5\uc774\ub098 \uc815\ud654\ub97c \ubc1b\uc73c\uba74 \ubc14\ub85c \ud480\ub824\ub098\uace0, \uc544\ub2c8\uba74 \ucd5c\ub300 3\ud134 \ub4a4\uc5d0 \ub2e4\uc2dc \ud480\ub824\ub098\uc694. Ovaling\uc744 \ub3cc\ub85c \ub9cc\ub4dc\ub294 \uac74 \uba54\ub450\uc0ac\ubfd0\uc774\uc5d0\uc694."},
Jx(a,b,c){return a+" "+b+" \ub3d9\uc548 [[\ud53c\ud574 \uac10\uc18c]]\ub97c \uc918\uc694: \ubc1b\ub294 \ubaa8\ub4e0 \ud53c\ud574\uac00 "+c+"% \uc904\uc5b4\uc694."},
