Js(a,b,c,d){return""+a+"% \ud655\ub960\ub85c "+b+" "+c+" \ub3d9\uc548 [[\ucd9c\ud608]]\uc2dc\ucf1c\uc694 (\ud134\ub9c8\ub2e4 \uc0ac\uc6a9\uc790 <atk>\uacf5\uaca9\ub825</atk>\uc758 "+d+"% \ud53c\ud574)."},
JO(a,b){return a+" "+b+" \ub3d9\uc548 [[\ubc18\uc0ac]]\ub97c \uc918\uc694: \uc801\uc774 \uac70\ub294 \ub2e4\uc74c \uc57d\ud654 \ud6a8\uacfc\uac00 \uadf8 \uc801\uc5d0\uac8c \ub418\ub3cc\uc544\uac00\uc694."},
JF(a,b){return a+" [[\ubc29\ud574]]\ud574\uc694: \ucfe8\ud0c0\uc784\uc774 \uc788\ub294 \uc2a4\ud0ac\uc774 \uc900\ube44\ub418\uae30\uae4c\uc9c0 "+b+" \ub354 \uac78\ub824\uc694."},
JG(a,b,c){return""+a+"% \ud655\ub960\ub85c "+b+" [[\ubc29\ud574]]\ud574\uc694: \ucfe8\ud0c0\uc784\uc774 \uc788\ub294 \uc2a4\ud0ac\uc774 \uc900\ube44\ub418\uae30\uae4c\uc9c0 "+c+" \ub354 \uac78\ub824\uc694."},
JH(a,b,c){return a+" "+b+" \ub3d9\uc548 [[\uc0dd\uba85\uc758 \ubd88\uc528]]\ub97c \uc918\uc694: \uc4f0\ub7ec\uc838\ub3c4 \ubc14\ub85c \ucd5c\ub300 <hp>\uccb4\ub825</hp>\uc758 "+c+"%\ub85c \uc77c\uc5b4\ub098\uc694 (\uc804\ud22c\ub9c8\ub2e4 \ud55c \ubc88)."},
Jj(a){return"\uce58\uba85\ud0c0\uac00 \ub098\uc62c \ub54c\ub9c8\ub2e4 \ud55c \ubc88 \ub354 \uacf5\uaca9\ud574\uc694 (\ucd5c\ub300 "+a+"\ud68c \ucd94\uac00)."},
xL(a){return"\uce58\uba85\ud0c0 \uc5f0\uc1c4 +"+a},
R3(a){return"\uc774 Ovaling\uc758 <fx:heal>\ud68c\ubcf5</fx>\uacfc <fx:shield>\ubcf4\ud638\ub9c9</fx>\uc774 "+a+"% \uac15\ud574\uc838\uc694."},
Rb(a){return"\ubaa8\ub4e0 \uc804\ud22c\uac00 \uc2dc\uc791\ub420 \ub54c \ud300 \uc804\uccb4\uac00 \ucd5c\ub300 <hp>\uccb4\ub825</hp>\uc758 "+a+"% <fx:shield>\ubcf4\ud638\ub9c9</fx>\uc744 \ubc1b\uc544\uc694."},
QY(a){return"\uc790\uc2e0\uc758 \uce58\uba85\ud0c0\uac00 \ub300\uc0c1\uc744 2\ud134 \ub3d9\uc548 <fx:bleed>\ucd9c\ud608</fx>\uc2dc\ucf1c\uc694 (\ud134\ub9c8\ub2e4 \uc790\uc2e0 <atk>\uacf5\uaca9\ub825</atk>\uc758 "+a+"% \ud53c\ud574)."},
